    private val decodedCache = HashMap<String, List<List<DoubleArray>>>()

    private fun decode(encoded: String): List<List<DoubleArray>> =
        encoded.split(";").map { poly ->
            poly.split("|").map { ring ->
                val nums = ring.split(" ").flatMap { it.split(",") }
                DoubleArray(nums.size) { i -> nums[i].toDouble() }
            }
        }

    @Synchronized
    private fun getDecoded(boundary: BoundaryDef): List<List<DoubleArray>> {
        val cacheKey = "${boundary.prefectureName}_${boundary.name}_${boundary.adminLevel}"
        return decodedCache.getOrPut(cacheKey) {
            decode(boundary.encodedPolys)
        }
    }

    /** 境界内に含まれるか判定 (bbox早期スキップ + ray casting)。 */
    fun contains(boundary: BoundaryDef, latitude: Double, longitude: Double): Boolean {
        if (latitude < boundary.latMin || latitude > boundary.latMax ||
            longitude < boundary.lonMin || longitude > boundary.lonMax) {
            return false
        }
        val polys = getDecoded(boundary)
        for (poly in polys) {
            if (poly.isEmpty()) continue
            if (!pointInRing(poly[0], longitude, latitude)) continue
            var inHole = false
            for (i in 1 until poly.size) {
                if (pointInRing(poly[i], longitude, latitude)) {
                    inHole = true
                    break
                }
            }
            if (!inHole) return true
        }
        return false
    }

    /** 指定の県・座標に対応する市・町・村 (admin_level=7) を探す。 */
    fun findCityOrTown(prefectureName: String?, latitude: Double, longitude: Double): String? {
        for (b in ALL) {
            if (b.adminLevel != 7) continue
            if (prefectureName != null && b.prefectureName != prefectureName) continue
            if (contains(b, latitude, longitude)) return b.name
        }
        return null
    }

    /** 指定の市・座標に対応する区 (admin_level=8) を探す。 */
    fun findWard(prefectureName: String?, cityName: String?, latitude: Double, longitude: Double): String? {
        for (b in ALL) {
            if (b.adminLevel != 8) continue
            if (prefectureName != null && b.prefectureName != prefectureName) continue
            if (cityName != null && b.parentCity != cityName) continue
            if (contains(b, latitude, longitude)) return b.name
        }
        return null
    }

    /** ray casting (even-odd)。x=lon, y=lat。 */
    private fun pointInRing(ring: DoubleArray, x: Double, y: Double): Boolean {
        var inside = false
        var j = ring.size - 2
        var i = 0
        while (i < ring.size) {
            val xi = ring[i]
            val yi = ring[i + 1]
            val xj = ring[j]
            val yj = ring[j + 1]
            if ((yi > y) != (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) {
                inside = !inside
            }
            j = i
            i += 2
        }
        return inside
    }
